 async function createDatabase(){const name=databaseName.trim(),slug=name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!name||!slug){setBuilderError('Enter a database name using letters or numbers.');return}const schemaName=`practice_${slug.replace(/-/g,'_')}`;setBuilderError('');setBuilderBusy(true);try{const r=await fetch(API+'/api/databases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,slug,schemaName,description:databaseDescription.trim()})});const x=await r.json();if(!r.ok)throw Error(x.error?.formErrors?.[0]||x.error||'Database creation failed');const list=await fetch(API+'/api/databases').then(y=>y.json());setDbs(list);setDb(list.find((d:DB)=>d.id===x.id)||list[0]);setNewDatabaseOpen(false);setDatabaseName('');setDatabaseDescription('');setMessage(`Database ${name} created`)}catch(e){setBuilderError((e as Error).message)}finally{setBuilderBusy(false)}}
 async function loadDb(d:DB){const [t,q,schema,sets,companies]=await Promise.all([fetch(`${API}/api/databases/${d.id}/tables`).then(r=>r.json()),fetch(`${API}/api/questions?databaseId=${d.id}`).then(r=>r.json()),fetch(`${API}/api/databases/${d.id}/schema`).then(r=>r.json()),fetch(`${API}/api/question-sets?databaseId=${d.id}`).then(r=>r.json()),fetch(`${API}/api/collections?databaseId=${d.id}`).then(r=>r.json())]);setTables(t);setQuestions(q);setRelationships(schema.relationships||[]);setQuestionSets(sets);setCompanyCollections(companies);setQuestionBankLabel('');setTopicFilter('all');setDifficultyFilter('all');const params=new URLSearchParams(location.search);if(params.get('revision')==='1'){const statuses=await loadRevisionStatuses(d.id),requestedId=params.get('questionId');setRevisionStatuses(statuses);setRevisionMode(true);setPracticeMode(false);const marked=q.find((item:Q)=>item.id===requestedId&&statuses[item.id]?.marked)||q.find((item:Q)=>statuses[item.id]?.marked);if(marked)selectQuestion(marked);else{setSelected(null);setExpected(null);setResult(null);updateSql('');setMessage('No questions in this database are marked for revision')}}else{setRevisionMode(false);setPracticeMode(false);const requestedId=params.get('questionId'),requested=q.find((item:Q)=>item.id===requestedId);if(requested)selectQuestion(requested);else if(q[0])selectQuestion(q[0]);else{setSelected(null);setExpected(null);updateSql('')}}}
 const filteredQuestions=questions.filter(q=>(topicFilter==='all'||q.topic===topicFilter)&&(difficultyFilter==='all'||q.difficulty===difficultyFilter));
