 function openReviewQueue(mode:'revision'|'practice'|'all'){const list=mode==='revision'?revisionQuestions:mode==='practice'?needsPracticeQuestions:filteredQuestions;setRevisionMode(mode==='revision');setPracticeMode(mode==='practice');if(list[0])selectQuestion(list[0]);else{setSelected(null);setExpected(null);setResult(null);updateSql('')}}
