 function addBuilderColumn(){setBuilderColumns((cols:any[])=>[...cols,{name:`column_${cols.length+1}`,type:'TEXT',primary:false,nullable:true,referencesTable:'',referencesColumn:''}])}
 async function createBuilderTable(){if(!db)return;const name=builderTable.trim(),validName=/^[a-zA-Z_][a-zA-Z0-9_]*$/;if(!validName.test(name)){setBuilderError('Table names must start with a letter or underscore and contain only letters, numbers, or underscores.');return}if(!builderColumns.length||builderColumns.some(c=>!validName.test(c.name.trim()))){setBuilderError('Every column needs a valid SQL identifier.');return}if(new Set(builderColumns.map(c=>c.name.trim().toLowerCase())).size!==builderColumns.length){setBuilderError('Column names must be unique.');return}const allowedTypes=['INTEGER','BIGINT','TEXT','VARCHAR(255)','NUMERIC','BOOLEAN','DATE','TIMESTAMP'];if(builderColumns.some(c=>!allowedTypes.includes(c.type))){setBuilderError('Choose a supported column type.');return}for(const column of builderColumns){if(column.referencesTable){const target=tables.find(t=>t.name===column.referencesTable);if(!target?.columns.some((c:any)=>c.column_name===column.referencesColumn)){setBuilderError(`Choose a valid foreign-key target for ${column.name}.`);return}}}const primary=builderColumns.filter(c=>c.primary);const definitions=builderColumns.map(c=>`"${c.name.trim()}" ${c.type}${!c.nullable&&!c.primary?' NOT NULL':''}`);if(primary.length)definitions.push(`PRIMARY KEY (${primary.map(c=>`"${c.name.trim()}"`).join(', ')})`);for(const column of builderColumns.filter(c=>c.referencesTable))definitions.push(`FOREIGN KEY ("${column.name.trim()}") REFERENCES "${column.referencesTable}" ("${column.referencesColumn}")`);const ddl=`CREATE TABLE "${name}" (\n  ${definitions.join(',\n  ')}\n);`;setBuilderError('');setBuilderBusy(true);try{const r=await fetch(`${API}/api/databases/${db.id}/import`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sql:ddl})});const x=await r.json();if(!r.ok)throw Error(x.error||'Table creation failed');setTables(x.tables);setBuilderOpen(false);setBuilderTable('');setBuilderColumns([{name:'id',type:'INTEGER',primary:true,nullable:false,referencesTable:'',referencesColumn:''}]);setMessage(`Table ${name} created`)}catch(e){setBuilderError((e as Error).message)}finally{setBuilderBusy(false)}}
 async function loadAttempts(id:string){const r=await fetch(`${API}/api/questions/${id}/attempts`);setAttempts(await r.json())}
 useEffect(()=>{fetch(API+'/api/auth/me',{credentials:'include'}).then(async r=>{const data=await r.json();if(!r.ok)throw Error(data.error||'Authentication required');setCurrentUser(data.user)}).catch(()=>{location.href='/login'}).finally(()=>setAuthChecking(false))},[]);useEffect(()=>{if(currentUser)loadDatabases()},[currentUser?.id]);useEffect(()=>{if(db)loadDb(db)},[db?.id]);
 async function loadRevisionStatuses(databaseId:string){const r=await fetch(`${API}/api/revision-status?databaseId=${encodeURIComponent(databaseId)}`,{headers:{'x-practice-session':sessionId}});const rows=await r.json();if(!r.ok)throw Error(rows.error||'Could not load revision status');const statuses=Object.fromEntries(rows.map((row:RevisionStatus)=>[row.id,row]));setRevisionStatuses(statuses);return statuses}
 async function toggleRevisionMark(){if(!selected||!db)return;const marked=!revisionStatuses[selected.id]?.marked;try{const r=await fetch(`${API}/api/questions/${selected.id}/revision-mark`,{method:'PUT',headers:{'Content-Type':'application/json','x-practice-session':sessionId},body:JSON.stringify({marked})});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not update revision mark');const statuses=await loadRevisionStatuses(db.id);setMessage(marked?'Marked for revision':'Revision mark removed');if((revisionMode&&!marked)||(practiceMode&&marked))advanceRevision(statuses,selected.id)}catch(e){setMessage((e as Error).message)}}
 async function run(){if(!db)return;setRunning(true);setMessage('Executing...');try{const r=await fetch(API+'/api/sql/execute',{method:'POST',headers:{'Content-Type':'application/json','x-practice-session':sessionId},body:JSON.stringify({databaseId:db.id,sql})});const x=await r.json();if(!r.ok)throw Error(x.error);setResult(x);setMessage(`${x.rowCount} rows · ${x.executionMs} ms`)}catch(e){setResult(null);setMessage((e as Error).message)}finally{setRunning(false)}}
 async function submit(){if(!selected||!db)return;setRunning(true);try{const r=await fetch(`${API}/api/questions/${selected.id}/submit`,{method:'POST',headers:{'Content-Type':'application/json','x-practice-session':sessionId},body:JSON.stringify({sql,isRevision:revisionMode||practiceMode})});const x=await r.json();if(x.correct){setResult(x.result);setMessage('✓ Correct — output matches expected result')}else{setMessage(x.error||'Incorrect — result does not match expected output');if(x.result)setResult(x.result)}await loadAttempts(selected.id);const statuses=await loadRevisionStatuses(db.id);if((revisionMode||practiceMode)&&x.correct)advanceRevision(statuses,selected.id)}finally{setRunning(false)}}
 async function generate(){if(!db){setMessage('Create or select a database before generating questions.');return}setGenerating(true);setMessage(`Generating ${genCount} validated questions...`);try{const r=await fetch(API+'/api/questions/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({databaseId:db.id,count:genCount,difficulty,topic})});const x=await r.json();if(!r.ok)throw Error(x.error);const sets=await fetch(`${API}/api/question-sets?databaseId=${db.id}`).then(y=>y.json());setQuestionSets(sets);setMessage(`Accepted ${x.accepted.length}; rejected ${x.rejected.length}`);setGenOpen(false);const generatedSet=sets.find((set:QuestionSet)=>set.id===x.setId);if(generatedSet){setCatalogView('sets');await openQuestionSet(generatedSet)}else setQuestions(current=>[...x.accepted,...current])}catch(e){setMessage((e as Error).message)}finally{setGenerating(false)}}
 async function importSql(){if(!db||!file)return;const fd=new FormData();fd.append('file',file);fd.append('databaseId',db.id);setMessage('Importing SQL...');const r=await fetch(API+'/api/databases/import-file',{method:'POST',body:fd});const x=await r.json();if(!r.ok)throw Error(x.error);setTables(x.tables);setFile(null);setImportOpen(false);setMessage('SQL schema/data imported');}
 async function importImage(){if(!file){setImportError('Select a schema image first.');return}if(!db&&!createDatabaseFromImage){setImportError('Select or create a database before extracting a schema.');return}const type=imageMime(file);if(!type){setImportError('Choose a PNG, JPEG, or WEBP schema image.');return}const imageFile=file.type===type?file:new File([file],file.name,{type});const fd=new FormData();fd.append('file',imageFile,file.name);if(createDatabaseFromImage)fd.append('createDatabase','true');else if(db)fd.append('databaseId',db.id);setImportError('');setImporting(true);try{const r=await fetch(API+'/api/databases/import-image',{method:'POST',body:fd});const x=await r.json();if(!r.ok)throw Error(x.error||'Schema extraction failed');if(x.database){setDbs((items:DB[])=>[x.database,...items.filter(item=>item.id!==x.database.id)]);setDb(x.database)}setIncludeSampleData(Boolean(x.plan.sampleDataSql));setImageReview(x);setImportOpen(false)}catch(e){setImportError((e as Error).message)}finally{setImporting(false)}}
 async function approveImageImport(){const target=imageReview?.database||db;if(!target||!imageReview)return;setImportError('');setImporting(true);try{const r=await fetch(`${API}/api/databases/${target.id}/import-review/${imageReview.importId}/approve`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({includeSampleData})});const x=await r.json();if(!r.ok)throw Error(x.error||'Schema approval failed');setTables(x.tables);setImageReview(null);setFile(null);setMessage(x.sampleDataIncluded?'Schema created with sample data':'Schema created without sample data')}catch(e){setImportError((e as Error).message)}finally{setImporting(false)}}
 async function tutor(action:string){if(!selected){setTutorText('Select a challenge first.');setAiOpen(true);return}setAiOpen(true);setTutorText('Thinking...');const r=await fetch(API+'/api/ai/tutor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,question:selected.task,schema:JSON.stringify(tables),sql})});const x=await r.json();setTutorText(x.answer||x.error)}
