 {builderOpen&&<div className="modalBackdrop" onClick={()=>setBuilderOpen(false)}><div className="smallModal schemaBuilderModal" onClick={e=>e.stopPropagation()}><div className="modalHeader"><div><b>Manual schema builder</b><small>{db?.name}</small></div><button aria-label="Close" onClick={()=>setBuilderOpen(false)}><X/></button></div><div className="importBody"><label>Table name<input autoFocus value={builderTable} onChange={e=>setBuilderTable(e.target.value)} placeholder="orders"/></label><div className="builderColumns">{builderColumns.map((column:any,index:number)=><div className="builderColumn" key={index}><label>Column<input value={column.name} onChange={e=>setBuilderColumns((cols:any[])=>cols.map((c,i)=>i===index?{...c,name:e.target.value}:c))}/></label><label>Type<select value={column.type} onChange={e=>setBuilderColumns((cols:any[])=>cols.map((c,i)=>i===index?{...c,type:e.target.value}:c))}>{['INTEGER','BIGINT','TEXT','VARCHAR(255)','NUMERIC','BOOLEAN','DATE','TIMESTAMP'].map(type=><option key={type}>{type}</option>)}</select></label><label className="builderCheck">Primary key<input type="checkbox" checked={column.primary} onChange={e=>setBuilderColumns((cols:any[])=>cols.map((c,i)=>i===index?{...c,primary:e.target.checked,nullable:e.target.checked?false:c.nullable}:c))}/></label><label className="builderCheck">Nullable<input type="checkbox" checked={column.nullable} disabled={column.primary} onChange={e=>setBuilderColumns((cols:any[])=>cols.map((c,i)=>i===index?{...c,nullable:e.target.checked}:c))}/></label><label>References table<select value={column.referencesTable} onChange={e=>setBuilderColumns((cols:any[])=>cols.map((c,i)=>i===index?{...c,referencesTable:e.target.value,referencesColumn:''}:c))}><option value="">None</option>{tables.map(table=><option key={table.name}>{table.name}</option>)}</select></label><label>Column<select value={column.referencesColumn} disabled={!column.referencesTable} onChange={e=>setBuilderColumns((cols:any[])=>cols.map((c,i)=>i===index?{...c,referencesColumn:e.target.value}:c))}><option value="">Select column</option>{(tables.find(table=>table.name===column.referencesTable)?.columns||[]).map((c:any)=><option key={c.column_name}>{c.column_name}</option>)}</select></label><button disabled={builderColumns.length===1} onClick={()=>setBuilderColumns((cols:any[])=>cols.filter((_:any,i:number)=>i!==index))}>Remove column</button></div>)}</div><button onClick={addBuilderColumn}>Add column</button>{builderError&&<div className="errorBox" role="alert">{builderError}</div>}<div className="importFooter"><button onClick={()=>setBuilderOpen(false)}>Cancel</button><button disabled={builderBusy||!builderTable.trim()} onClick={createBuilderTable}>{builderBusy?'Creating...':'Create table'}</button></div></div></div></div>}
 {tablePreview&&<div className="modalBackdrop" onClick={()=>setTablePreview(null)}><div className="smallModal tablePreviewModal" onClick={e=>e.stopPropagation()}><div className="modalHeader"><div><b>{tablePreview.table}</b><small>{tablePreview.total} rows · table data</small></div><button aria-label="Close table data" onClick={()=>setTablePreview(null)}><X/></button></div>{tablePreviewError?<div className="errorBox" role="alert">{tablePreviewError}</div>:tablePreviewLoading?<div className="empty">Loading rows...</div>:<div className="previewTableScroll"><table><thead><tr>{tablePreview.columns.map(column=><th key={column}>{column}</th>)}</tr></thead><tbody>{tablePreview.rows.map((row,index)=><tr key={index}>{tablePreview.columns.map(column=><td key={column}>{String(row[column]??'NULL')}</td>)}</tr>)}</tbody></table></div>}<div className="previewPager"><button disabled={tablePreviewLoading||tablePreview.offset===0} onClick={()=>openTablePreview(tablePreview.table,Math.max(0,tablePreview.offset-tablePreview.limit))}>Previous</button><span>{tablePreview.total?`${tablePreview.offset+1}–${Math.min(tablePreview.offset+tablePreview.rows.length,tablePreview.total)} of ${tablePreview.total}`:'0 rows'}</span><button disabled={tablePreviewLoading||tablePreview.offset+tablePreview.limit>=tablePreview.total} onClick={()=>openTablePreview(tablePreview.table,tablePreview.offset+tablePreview.limit)}>Next</button></div></div></div>}
